const RolloutRefreshTargetFromLatestAttempt = `-- name: RolloutRefreshTargetFromLatestAttempt :exec
UPDATE rollout_targets rt
SET
    status = v.new_status,
    err_message = v.err_message,
    updated_at = now ()
FROM (
    SELECT
        rt2.id,
        CASE
            WHEN mca.status = 'completed' THEN 'succeeded'::text
            WHEN mca.status IN (
                'failed',
                'nack',
                'ack_timeout'
            ) THEN 'failed'::text
            WHEN mca.status IN ('pending', 'sent') THEN 'dispatched'::text
            ELSE rt2.status::text
        END AS new_status,
        CASE
            WHEN mca.status IN (
                'failed',
                'nack',
                'ack_timeout'
            ) THEN COALESCE(mca.timeout_reason, mca.status)
            ELSE rt2.err_message
        END AS err_message
    FROM rollout_targets rt2
    LEFT JOIN LATERAL (
        SELECT
            status,
            timeout_reason
        FROM machine_command_attempts
        WHERE
            command_id = rt2.command_id
        ORDER BY attempt_no DESC
        LIMIT 1
    ) mca ON rt2.command_id IS NOT NULL
    WHERE
        rt2.campaign_id = $1
        AND TRUE
        AND rt2.command_id IS NOT NULL
        AND rt2.status NOT IN ('skipped', 'rolled_back')
) AS v
WHERE
    rt.id = v.id
    AND rt.status IN ('pending', 'dispatched', 'acknowledged')
    AND v.new_status IS NOT NULL
    AND v.new_status <> rt.status::text
`

func (q *Queries) RolloutRefreshTargetFromLatestAttempt(ctx context.Context, campaignID uuid.UUID) error {
	_, err := q.db.Exec(ctx, RolloutRefreshTargetFromLatestAttempt, campaignID)
	return err
}

